package com.tuap.backend.auth;
import java.security.SecureRandom; import java.time.*; import java.util.*; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
import com.tuap.backend.dominio.entidades.*; import com.tuap.backend.persistencia.*;
@Service public class ReauthenticationService {
 private static final SecureRandom RANDOM=new SecureRandom(); private final ReauthenticationTokenDAO tokens; private final AuthIdentityDAO identities; private final IdentityResolver users; private final ClienteDAO clientes; private final EntrenadorDAO entrenadores; private final PasswordEncoder passwords; private final ReauthenticationProperties properties; private final Clock clock;
 @org.springframework.beans.factory.annotation.Autowired public ReauthenticationService(ReauthenticationTokenDAO t,AuthIdentityDAO i,IdentityResolver u,ClienteDAO c,EntrenadorDAO e,PasswordEncoder p,ReauthenticationProperties x){this(t,i,u,c,e,p,x,Clock.systemUTC());}
 ReauthenticationService(ReauthenticationTokenDAO t,AuthIdentityDAO i,IdentityResolver u,ClienteDAO c,EntrenadorDAO e,PasswordEncoder p,ReauthenticationProperties x,Clock k){tokens=t;identities=i;users=u;clientes=c;entrenadores=e;passwords=p;properties=x;clock=k;}
 @Transactional public ReauthTokenResponse password(AuthenticatedUser user,String password,AuthProvider target){validateTarget(target);requireActive(user);if(!hasLocal(user))throw new LocalIdentityNotAvailableException();String stored=user.role()==Role.CLIENTE?clientes.findById(user.userId()).map(Cliente::getContrasena).orElse(null):entrenadores.findById(user.userId()).map(Entrenador::getContrasena).orElse(null);if(stored==null||password==null||!passwords.matches(password,stored))throw new org.springframework.security.authentication.BadCredentialsException("invalid");return issue(user,target,ReauthenticationPurpose.IDENTITY_UNLINK);}
 @Transactional public ReauthTokenResponse provider(AuthenticatedUser user,VerifiedSocialIdentity verified,AuthProvider target){validateTarget(target);requireProvider(user,verified);if(verified.provider()==target)throw new InvalidReauthenticationTokenException();return issue(user,target,ReauthenticationPurpose.IDENTITY_UNLINK);}
 @Transactional public ReauthTokenResponse providerForCreateLocal(AuthenticatedUser user,VerifiedSocialIdentity verified){requireActive(user);if(hasLocal(user))throw new LocalIdentityAlreadyExistsException();requireProvider(user,verified);return issue(user,null,ReauthenticationPurpose.CREATE_LOCAL_IDENTITY);}
 @Transactional public void consumeForUnlink(AuthenticatedUser user,AuthProvider target,String raw){consume(user,raw,ReauthenticationPurpose.IDENTITY_UNLINK,target);}
 @Transactional public void consumeForCreateLocal(AuthenticatedUser user,String raw){consume(user,raw,ReauthenticationPurpose.CREATE_LOCAL_IDENTITY,null);}
 private void consume(AuthenticatedUser user,String raw,ReauthenticationPurpose purpose,AuthProvider target){if(raw==null||raw.isBlank())throw new InvalidReauthenticationTokenException();ReauthenticationToken t=tokens.findLockedByTokenHash(PasswordResetService.hash(raw)).orElseThrow(InvalidReauthenticationTokenException::new);if(!t.isUsableAt(clock.instant())||!t.getUserId().equals(user.userId())||t.getRole()!=user.role()||t.getPurpose()!=purpose||t.getTargetProvider()!=target)throw new InvalidReauthenticationTokenException();t.consume(clock.instant());}
 private void requireProvider(AuthenticatedUser user,VerifiedSocialIdentity verified){requireActive(user);AuthIdentity i=identities.findByProviderAndProviderSubject(verified.provider(),verified.providerSubject()).orElseThrow(InvalidReauthenticationTokenException::new);if(!i.isActive()||!i.getUserId().equals(user.userId())||i.getRole()!=user.role())throw new InvalidReauthenticationTokenException();}
 private ReauthTokenResponse issue(AuthenticatedUser user,AuthProvider target,ReauthenticationPurpose purpose){byte[] bytes=new byte[32];RANDOM.nextBytes(bytes);String raw=Base64.getUrlEncoder().withoutPadding().encodeToString(bytes);Instant now=clock.instant();tokens.save(new ReauthenticationToken(PasswordResetService.hash(raw),user.userId(),user.role(),target,purpose,now,now.plus(Duration.ofMinutes(properties.getTtlMinutes()))));return new ReauthTokenResponse(raw,Duration.ofMinutes(properties.getTtlMinutes()).toSeconds());}
 private boolean hasLocal(AuthenticatedUser u){return identities.existsByUserIdAndRoleAndProviderAndActiveTrue(u.userId(),u.role(),AuthProvider.LOCAL);} private void requireActive(AuthenticatedUser u){if(u==null||users.findByIdAndRole(u.userId(),u.role()).isEmpty())throw new AccountInactiveException();} private void validateTarget(AuthProvider t){if(t!=AuthProvider.GOOGLE&&t!=AuthProvider.APPLE)throw new InvalidReauthenticationTokenException();}
}
